import{z as n,x as i,o as l,c as h,q as r,j as o,D as e,d as E,s,S as d}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"GSPMD","description":"","frontmatter":{"title":"GSPMD","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gspmd.md","filePath":"llm/gspmd.md","lastUpdated":1791063341000}'),A={name:"llm/gspmd.md"};function p(B,a,m,P,c,D){const t=i("Mermaid");return l(),h("div",null,[a[2]||(a[2]=r('<h1 id="gspmd" tabindex="-1">GSPMD <a class="header-anchor" href="#gspmd" aria-label="Permalink to &quot;GSPMD&quot;">​</a></h1><div class="epigraph"><p>程序仍按单设备写，只在少数张量上标注如何沿设备网格切开；编译器把切分推到整张计算图，并插入集合通信，使每台设备跑同一份 SPMD 程序。</p><footer>—— Xu 等，GSPMD: General and Scalable Parallelization for ML Computation Graphs, 2021</footer></div><p>GPU 栈里，数据并行、张量并行、流水线往往是三套运行时、三种通信组。Google 的 XLA 走另一条路：把并行收成<strong>张量切分标注</strong>，由编译器完成传播与改写。Xu、Lee、Chen 等人 2021 年的 GSPMD（General and Scalable Parallelization for ML Computation Graphs）把这条路写成可生产使用的分区器：有限标注、整图推断、一份程序跑所有设备。论文报告在最多 2048 个 Cloud TPU v3 核心上，对最大约万亿参数的模型达到 50%–62% 的算力利用率。本篇写分区语义与传播，不把 <a href="/llm/gshard">GShard</a> 的 MoE 翻译实验再写一遍，也不把 <a href="/llm/pathways">Pathways</a> 的调度层提前做成 GSPMD 的能力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写并行有两头痛。一头是正确性：All-Reduce 该加在哪条边上、分片轴是否与点积的收缩维对齐、卷积的 halo 要不要交换，漏一次就静默错数。另一头是组合：数据并行切 batch、层内并行切隐藏维、空间并行切图像、权重更新再切一份、流水线切层——每加一维就改一遍算子。模型开发者被逼着把网络定义与设备拓扑焊死。</p><p>GSPMD 要的分离是：网络仍看成一块巨大的逻辑张量；用户只在关键输入、权重或激活上给出 <code>mesh_split</code> 一类提示；其余算子的切分由编译器补全，并插入 All-Reduce、All-Gather、Reduce-Scatter、halo exchange 等，使分片后的图与单设备图数学等价。换策略时改标注，不改层定义。</p><h3 id="一种切分表示覆盖多种并行" tabindex="-1">一种切分表示覆盖多种并行 <a class="header-anchor" href="#一种切分表示覆盖多种并行" aria-label="Permalink to &quot;一种切分表示覆盖多种并行&quot;">​</a></h3><p>论文强调表示简单但够用：张量沿设备 <strong>mesh</strong> 的某些轴切开，其余轴复制。数据并行是 batch 维对准 mesh 的 replica / data 轴；层内模型并行是隐藏维对准 model 轴；图像模型的空间切分是高宽维对准 mesh；稀疏专家是专家维对准 mesh。流水线被收成「沿层方向的向量化移位缓冲」上的张量切分，而不是另写一套运行时。于是「混合并行」变成「同一张量不同维切在不同 mesh 轴上」，而不是多个互不认识的通信库。</p><p><span class="marginnote">mesh 就是把几百上千个芯片排成一个虚拟的多维格子（如 16×64 的「行×列」），每个张量维度对准格子的某条轴去切。物理连线不动，换并行策略只是换「哪个维度对准哪条轴」，这就是它比三套运行时省事的地方。</span></p><p><span class="marginnote">SPMD 的意思是所有设备跑同一份程序，用设备坐标去取自己的片。MPMD（每台设备不同程序）更适合异构流水，但难生成、难调试。GSPMD 押 SPMD，是为了和 XLA 的整图编译、静态形状友好的 TPU 内核一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户在 TensorFlow 或 JAX 里写单设备数值，在少数张量上调用切分 API（论文中的 mesh 标注；JAX 后来经 <code>NamedSharding</code> / <code>PartitionSpec</code> 把意图编进 StableHLO，再由 XLA 里的 GSPMD 读取）。编译器做两件事。</p><p><strong>传播</strong>：类似类型推断。已知部分张量的切分，按算子语义推出操作数与结果应如何切。矩阵乘在收缩维对齐时变成各设备本地 GEMM 加 All-Reduce；收缩维被切而对方未切时，可能先 Gather 再乘。逐元素算子沿同维传播切分。归约若沿着被切的轴，就变成局部归约加跨设备 All-Reduce。冲突时用优先级与启发式——生产系统必须处理「用户只标了权重、激活未标」这种残缺输入。</p><p><span class="marginnote">数字感受一下通信代价：\\(d=4096\\) 的激活按 bf16 存约每位置 8 KB，若它在 model 轴切成 8 份而下游算子要完整视图，All-Gather 每设备要收回其余 7 份，约 56 KB/位置。所以好标注让乘法在本地完成，通信只留给真正跨设备求和的那一步。</span></p><p><strong>改写</strong>：把逻辑图变成每设备图，插入通信，使每个设备只看见自己的片。这就是分区器（partitioner）。输出仍是一份 HLO，所有 TPU 核心执行它。论文把这条路径用到稠密 Transformer、稀疏 MoE、三维 U-Net 等，并开源 Lingvo 配置供 Cloud TPU 复现。Google 后续博文还给出若干大模型利用率：例如 LaMDA 级稠密解码器在 1024 个 TPU v3 上约 56.5%，MLPerf BERT 级约 480B 在 2048 个 TPU v4 上约 63%。那些数字属于特定模型与特定 MLPerf / 内部配置，不是分区器的常数。</p>',15)),(l(),o(d,null,{default:e(()=>[s(t,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8D%95%E8%AE%BE%E5%A4%87%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20A%5B%22%E5%B0%91%E6%95%B0%E5%BC%A0%E9%87%8F%E5%88%87%E5%88%86%E6%A0%87%E6%B3%A8%22%5D%0A%20%20A%20--%3E%20I%5B%22%E5%88%87%E5%88%86%E4%BC%A0%E6%92%AD%22%5D%0A%20%20I%20--%3E%20R%5B%22SPMD%20%E6%94%B9%E5%86%99%20%2B%20%E6%8F%92%E5%85%A5%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%22%5D%0A%20%20R%20--%3E%20X%5B%22%E6%AF%8F%E8%AE%BE%E5%A4%87%E5%90%8C%E4%B8%80%E4%BB%BD%20XLA%20%E7%A8%8B%E5%BA%8F%22%5D%0A%20%20X%20--%3E%20M%5B%22TPU%20mesh%20%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h3 id="从-gshard-注解到通用分区器" tabindex="-1">从 GShard 注解到通用分区器 <a class="header-anchor" href="#从-gshard-注解到通用分区器" aria-label="Permalink to &quot;从 GShard 注解到通用分区器&quot;">​</a></h3><p>GShard 已经用轻量 API 加 XLA 扩展去切 MoE 翻译模型。GSPMD 把同一套思想泛化到「常见机器学习计算图」，并解决生产里的残缺标注、混合范式、内存与步时近线性扩展。可以把它看成 GShard 分区器的后继与推广：MoE 仍是切分的一种，而不是唯一客户。再往后，OpenXLA 的 <strong>Shardy</strong> 在 MLIR 里重做传播与分区，JAX 文档写明此前用户经 GSPMD 走 XLA HLO；迁移指南存在，本篇不把 Shardy 的方言细节写成 2021 年论文的内容。</p><p><code>jax.lax.with_sharding_constraint</code> 一类提示，相当于在中间张量上补锚点，防止传播选到通信更贵的切法。完全手动的 <code>shard_map</code> / 显式集合通信是另一条路：编译器少管，用户多写。GSPMD 的默认价值是「少写通信」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>传播能成立，是因为多数 ML 算子是张量代数：切分是维上的等价关系，可以沿数据流前进或后退。困难点在「切分与算子语义不一致」时必须通信。通信体积由<strong>被切开却需要完整视图的那些维</strong>决定。好的标注让收缩发生在本地，All-Reduce 只出现在真正需要求和的轴上；坏的标注会在每层 Gather 整份激活，步时被 ICI 吃掉。利用率 50%–62% 说明在论文的网格与模型上，通信没有把 TPU 脉动阵列饿死，不是说任意标注都能打到这个区间。</p><p>以最常见的矩阵乘为例，传播后的通信形态由收缩维的切分状态决定：</p>',6)),(l(),o(d,null,{default:e(()=>[s(t,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20MM%5B%22%E7%9F%A9%E9%98%B5%E4%B9%98%20Y%20%3D%20X%20%C2%B7%20W%22%5D%20--%3E%20Q%7B%22%E6%94%B6%E7%BC%A9%E7%BB%B4%20K%20%E7%9A%84%E5%88%87%E5%88%86%E6%98%AF%E5%90%A6%E5%AF%B9%E9%BD%90%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E4%B8%A4%E8%BE%B9%E9%83%BD%E6%B2%BF%20K%20%E5%88%87%22%7C%20AR%5B%22%E6%9C%AC%E5%9C%B0%E9%83%A8%E5%88%86%E4%B9%98%20%2B%20All-Reduce%20%E6%B1%82%E5%92%8C%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8F%AA%E6%9C%89%E4%B8%80%E8%BE%B9%E6%B2%BF%20K%20%E5%88%87%22%7C%20GA%5B%22%E5%85%88%20All-Gather%20%E6%8B%BC%E5%9B%9E%E6%95%B4%E4%BB%BD%E5%86%8D%E4%B9%98%22%5D%0A%20%20Q%20--%3E%7C%22K%20%E6%9C%AA%E5%88%87%22%7C%20LO%5B%22%E7%BA%AF%E6%9C%AC%E5%9C%B0%20GEMM%EF%BC%8C%E6%97%A0%E9%80%9A%E4%BF%A1%22%5D%0A%20%20AR%20--%3E%20EQ%5B%22%E7%BB%93%E6%9E%9C%E4%B8%8E%E5%8D%95%E8%AE%BE%E5%A4%87%E6%95%B0%E5%AD%A6%E7%AD%89%E4%BB%B7%22%5D%0A%20%20GA%20--%3E%20EQ%0A%20%20LO%20--%3E%20EQ%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>部分切分（partial tiling）允许一个张量在某些 mesh 轴上切、在另一些轴上复制。这是混合并行的代数形式：例如 batch 切在 data 轴、隐藏维切在 model 轴，权重在 data 轴复制、在 model 轴切开。权重更新还可以再切（weight-update sharding），让优化器状态不在所有副本上完整存在——精神上接近 ZeRO，但是由编译器插通信，而不是由数据并行运行时管生命周期。</p><p><span class="marginnote">可以把部分切分想象成分蛋糕：batch 这条维按「桌数」（data 轴）切，hidden 这条维按「每桌份数」（model 轴）切；权重只在份数方向切、桌数方向整份复制。一张标注表同时写清数据和权重各自的分法，不必为每种并行各写一套代码。</span></p><p><span class="marginnote">GSPMD 不调度跨 Pod 的异构任务，也不替代运行时的弹性。它假定一次编译看到的设备网格是静态的。网格跨越 ICI 与数据中心网络时，把哪一维放在慢网上，是用户的 mesh 轴选择问题，见 <a href="/llm/tpu-training">TPU 训练栈</a>。</span></p><h3 id="静态形状与动态稀疏" tabindex="-1">静态形状与动态稀疏 <a class="header-anchor" href="#静态形状与动态稀疏" aria-label="Permalink to &quot;静态形状与动态稀疏&quot;">​</a></h3><p>TPU 内核喜欢编译期已知的形状。MoE 的 token 数因路由而变，GShard / GSPMD 用容量因子把缓冲区做成静态上限：超容量则丢弃或溢出到备份，而不是运行时变长 All-to-All。这是编译器分区能处理稀疏计算的前提。动态控制流过多、自定义算子没有切分规则，传播会停，用户必须补标注或手写分区。这是边界，不是失败。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 GSPMD 理解成「全自动并行、零标注」。论文写的是 hints。标注切在错误的维上，编译器会忠实生成昂贵的通信。不要在 GPU 上假设同一套 XLA 分区器自动吃满 NVLink：GSPMD 的主战场是 XLA + TPU；GPU 上即便走 XLA，集体通信后端与拓扑启发式也不同。</p><p>不要把 2048 核心上的利用率抄到另一代 TPU 或另一模型当 KPI。不要填写未在论文或 Cloud 文档出现的 ICI 单通道速率。调试应先看切分传播后的 HLO：哪条边插入了 All-Gather，往往比看 Python 层的 <code>pjit</code> 更直接。</p><p><span class="marginnote">出处：Xu 等，<em>GSPMD</em>，arXiv:2105.04663；Google Research 博文 <em>General and Scalable Parallelization for Neural Networks</em>。JAX 侧今日默认分区器可能是 Shardy，读当时运行时的 <code>jax_use_shardy_partition</code> 一类标志，不要把 2021 年的 HLO 分区器当成 2026 年 JAX 的唯一实现。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GSPMD 是 XLA 里的编译期 SPMD 分区器：少量表切分标注，整图传播，插入集合通信。</li><li>数据、层内、空间、权重更新、以及收成张量切分的流水线，共用一种 mesh 切分表示。</li><li>论文在最多 2048 个 TPU v3 核心、最大约 1T 参数上报告 50%–62% 利用率；后续博文有其他模型的点值。</li><li>它推广 GShard 的分区思想，本身不是 MoE 路由算法，也不是集群调度器。</li><li>坏标注会产生合法但昂贵的通信；静态容量是稀疏层可编译的前提。</li><li>出处：Xu 等，<em>GSPMD</em>，2021；对照 <a href="/llm/gshard">GShard</a> 与 <a href="/llm/tpu-training">TPU 训练栈</a>。</li></ul>',11))])}const G=n(A,[["render",p]]);export{u as __pageData,G as default};
